:root {
  --bg: #1a1a2e;
  --panel: #16213e;
  --accent: #e94560;
  --accent-hover: #ff5c77;
  --text: #eaeaea;
  --muted: #8a8aa3;
  --yes: #2ecc71;
  --no: #e74c3c;
  --border: #2a2a4a;
  --radius: 10px;
  --font: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  background: var(--bg);
  background-image:
    linear-gradient(rgba(233,69,96,0.05) 1px, transparent 1px),
    linear-gradient(90deg, rgba(233,69,96,0.05) 1px, transparent 1px);
  background-size: 24px 24px;
  color: var(--text);
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.5;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  padding: 20px 12px;
}

.app {
  width: 100%;
  max-width: 560px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.pixel-title {
  font-size: 1.6rem;
  text-align: center;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--accent);
  text-shadow: 2px 2px 0 #000;
  padding: 8px 0;
}

.panel {
  background: var(--panel);
  border: 2px solid var(--border);
  border-radius: var(--radius);
  padding: 20px;
  box-shadow: 0 4px 0 #00000055;
}

.hidden { display: none !important; }

.card-form { display: flex; flex-direction: column; gap: 14px; }

.field { display: flex; flex-direction: column; gap: 6px; }

label { font-size: 0.9rem; color: var(--muted); font-weight: 600; text-transform: uppercase; letter-spacing: 0.5px; }

input, select {
  font-family: var(--font);
  font-size: 1rem;
  padding: 10px 12px;
  border-radius: 8px;
  border: 2px solid var(--border);
  background: #0f1629;
  color: var(--text);
  outline: none;
  transition: border-color 0.15s;
}

input:focus, select:focus { border-color: var(--accent); }

.btn {
  font-family: var(--font);
  font-size: 1rem;
  font-weight: 600;
  padding: 10px 18px;
  border: 2px solid transparent;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.15s, transform 0.05s, box-shadow 0.15s;
  min-height: 44px;
}

.btn:active:not(:disabled) { transform: translateY(2px); }
.btn:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }

.btn.primary { background: var(--accent); color: #fff; }
.btn.primary:hover:not(:disabled) { background: var(--accent-hover); }
.btn.primary:disabled { opacity: 0.4; cursor: not-allowed; }

.btn.play { background: var(--yes); color: #062b14; }
.btn.play:hover:not(:disabled) { background: #3fe085; }
.btn.play:disabled { opacity: 0.4; cursor: not-allowed; }

.btn.ghost { background: transparent; color: var(--text); border-color: var(--border); }
.btn.ghost:hover { border-color: var(--accent); color: var(--accent); }

.btn.yes { background: var(--yes); color: #062b14; flex: 1; }
.btn.yes:hover { background: #3fe085; }
.btn.no { background: var(--no); color: #fff; flex: 1; }
.btn.no:hover { background: #ff6b5b; }

.list-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin: 22px 0 12px;
  flex-wrap: wrap;
}

.list-header h2 { font-size: 1.1rem; display: flex; align-items: center; gap: 8px; }

.badge {
  background: var(--accent);
  color: #fff;
  font-size: 0.8rem;
  padding: 2px 9px;
  border-radius: 20px;
}

.card-list { list-style: none; display: flex; flex-direction: column; gap: 10px; }

.card-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  background: #0f1629;
  border: 2px solid var(--border);
  border-radius: 8px;
  padding: 10px 12px;
}

.card-item .q-text { flex: 1; word-break: break-word; }
.card-item .a-tag { font-size: 0.8rem; font-weight: 700; padding: 2px 8px; border-radius: 6px; }
.a-tag.yes { background: rgba(46,204,113,0.2); color: var(--yes); }
.a-tag.no { background: rgba(231,76,60,0.2); color: var(--no); }

.icon-btn {
  background: transparent;
  border: none;
  color: var(--muted);
  font-size: 1.1rem;
  cursor: pointer;
  padding: 6px 8px;
  border-radius: 6px;
  min-width: 36px;
  min-height: 36px;
}

.icon-btn:hover { color: var(--accent); background: rgba(233,69,96,0.1); }
.icon-btn:focus-visible { outline: 2px solid var(--accent); }

.empty-msg { color: var(--muted); text-align: center; padding: 16px 0; font-size: 0.95rem; }

.play-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 20px; }
.progress { color: var(--muted); font-size: 0.9rem; font-weight: 600; }

.question-box {
  background: #0f1629;
  border: 2px solid var(--border);
  border-radius: 8px;
  padding: 28px 18px;
  margin-bottom: 20px;
  min-height: 120px;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
}

.play-question { font-size: 1.2rem; font-weight: 600; }

.answer-buttons { display: flex; gap: 12px; }

.feedback { text-align: center; margin-top: 14px; font-weight: 700; min-height: 24px; }
.feedback.correct { color: var(--yes); }
.feedback.wrong { color: var(--no); }

.score-text { font-size: 2rem; font-weight: 800; text-align: center; color: var(--accent); margin: 10px 0; }
.score-detail { text-align: center; color: var(--muted); margin-bottom: 22px; }
.result-actions { display: flex; gap: 12px; flex-wrap: wrap; }
.result-actions .btn { flex: 1; }

@media (max-width: 400px) {
  .pixel-title { font-size: 1.3rem; }
  .panel { padding: 16px; }
  .result-actions { flex-direction: column; }
}

(function () {
  'use strict';

  var cards = [];
  var playIndex = 0;
  var correctCount = 0;
  var editingId = null;

  var editor = document.getElementById('editor');
  var play = document.getElementById('play');
  var results = document.getElementById('results');
  var cardForm = document.getElementById('card-form');
  var questionInput = document.getElementById('question-input');
  var answerSelect = document.getElementById('answer-select');
  var addBtn = document.getElementById('add-btn');
  var cardList = document.getElementById('card-list');
  var cardCount = document.getElementById('card-count');
  var playBtn = document.getElementById('play-btn');
  var emptyMsg = document.getElementById('empty-msg');
  var progress = document.getElementById('progress');
  var playQuestion = document.getElementById('play-question');
  var yesBtn = document.getElementById('yes-btn');
  var noBtn = document.getElementById('no-btn');
  var feedback = document.getElementById('feedback');
  var quitBtn = document.getElementById('quit-btn');
  var scoreText = document.getElementById('score-text');
  var scoreDetail = document.getElementById('score-detail');
  var restartBtn = document.getElementById('restart-btn');
  var backBtn = document.getElementById('back-btn');

  function renderList() {
    cardList.innerHTML = '';
    cardCount.textContent = cards.length;
    playBtn.disabled = cards.length === 0;
    emptyMsg.classList.toggle('hidden', cards.length > 0);

    cards.forEach(function (card, i) {
      var li = document.createElement('li');
      li.className = 'card-item';

      var q = document.createElement('span');
      q.className = 'q-text';
      q.textContent = (i + 1) + '. ' + card.question;

      var tag = document.createElement('span');
      tag.className = 'a-tag ' + card.answer;
      tag.textContent = card.answer.toUpperCase();

      var edit = document.createElement('button');
      edit.className = 'icon-btn';
      edit.textContent = '\u270E';
      edit.setAttribute('aria-label', 'Edit card ' + (i + 1));
      edit.addEventListener('click', function () { startEdit(card.id); });

      var del = document.createElement('button');
      del.className = 'icon-btn';
      del.textContent = '\u2715';
      del.setAttribute('aria-label', 'Delete card ' + (i + 1));
      del.addEventListener('click', function () { deleteCard(card.id); });

      li.appendChild(q);
      li.appendChild(tag);
      li.appendChild(edit);
      li.appendChild(del);
      cardList.appendChild(li);
    });
  }

  function startEdit(id) {
    var card = cards.find(function (c) { return c.id === id; });
    if (!card) return;
    editingId = id;
    questionInput.value = card.question;
    answerSelect.value = card.answer;
    addBtn.textContent = 'Save Card';
    questionInput.focus();
  }

  function resetForm() {
    editingId = null;
    cardForm.reset();
    addBtn.textContent = 'Add Card';
    questionInput.focus();
  }

  function deleteCard(id) {
    cards = cards.filter(function (c) { return c.id !== id; });
    if (editingId === id) resetForm();
    renderList();
  }

  cardForm.addEventListener('submit', function (e) {
    e.preventDefault();
    var question = questionInput.value.trim();
    var answer = answerSelect.value;
    if (!question) return;

    if (editingId !== null) {
      var card = cards.find(function (c) { return c.id === editingId; });
      if (card) {
        card.question = question;
        card.answer = answer;
      }
    } else {
      cards.push({ id: Date.now() + Math.random(), question: question, answer: answer });
    }
    resetForm();
    renderList();
  });

  function showPanel(panel) {
    [editor, play, results].forEach(function (p) { p.classList.add('hidden'); });
    panel.classList.remove('hidden');
  }

  function startPlay() {
    if (cards.length === 0) return;
    playIndex = 0;
    correctCount = 0;
    showPanel(play);
    showCurrentCard();
  }

  function showCurrentCard() {
    var card = cards[playIndex];
    progress.textContent = 'Card ' + (playIndex + 1) + ' of ' + cards.length;
    playQuestion.textContent = card.question;
    feedback.textContent = '';
    feedback.className = 'feedback';
    yesBtn.disabled = false;
    noBtn.disabled = false;
  }

  function answer(userAnswer) {
    var card = cards[playIndex];
    var isCorrect = userAnswer === card.answer;
    if (isCorrect) correctCount++;

    feedback.textContent = isCorrect ? 'Correct!' : 'Wrong! The answer was ' + card.answer.toUpperCase() + '.';
    feedback.className = 'feedback ' + (isCorrect ? 'correct' : 'wrong');
    yesBtn.disabled = true;
    noBtn.disabled = true;

    setTimeout(function () {
      playIndex++;
      if (playIndex < cards.length) {
        showCurrentCard();
      } else {
        showResults();
      }
    }, 900);
  }

  function showResults() {
    showPanel(results);
    scoreText.textContent = correctCount + ' / ' + cards.length;
    scoreDetail.textContent = 'You answered ' + correctCount + ' out of ' + cards.length + ' correctly.';
    restartBtn.focus();
  }

  yesBtn.addEventListener('click', function () { answer('yes'); });
  noBtn.addEventListener('click', function () { answer('no'); });
  playBtn.addEventListener('click', startPlay);
  quitBtn.addEventListener('click', function () { showPanel(editor); resetForm(); });
  restartBtn.addEventListener('click', startPlay);
  backBtn.addEventListener('click', function () { showPanel(editor); resetForm(); });

  renderList();
})();
